};

private const char *
cdf_clsid_to_mime(const uint64_t clsid[2], const struct cv *cv)
{
        size_t i;
        for (i = 0; cv[i].mime != NULL; i++) {
                if (clsid[0] == cv[i].clsid[0] && clsid[1] == cv[i].clsid[1])
                        return cv[i].mime;
        }
#ifdef CDF_DEBUG
        fprintf(stderr, "unknown mime %" PRIx64 ", %" PRIx64 "\n", clsid[0],
            clsid[1]);
#endif
        return NULL;
}

